export const LEGACY_SKILLS=BRANCHES.flatMap(b=>Array.from({length:20},(_,i)=>({id:b.id+'_'+(i+1),cost:1,requires:i?[b.id+'_'+i]:[]})));
export const BONUS_DEFAULTS=Object.fromEntries(['health','damage','ritual','speed','gold','xp',...SKILLS.flatMap(n=>Object.keys(n.effects))].map(k=>[k,0]));
export const skillText=(node,field,language='en')=>node[field]?.[language]||node[field]?.en||'';
export const prerequisitesMet=(s,n)=>n.requires.every(id=>s.skills.includes(id))&&(!n.anyRequires?.length||n.anyRequires.some(id=>s.skills.includes(id)));
